        'انقر المسطرة لتعيين رأس التشغيل. انقر شكل الموجة لإضافة عقدة.',
        'प्लेहेड सेट करने के लिए रूलर पर क्लिक करें। नोड जोड़ने के लिए तरंग पर क्लिक करें।',
