        'Режим продолжения (нажмите для смены):\nНет → Автопродолжение → Автоследование\n→  Автопродолжение (после пост-паузы)\n↳  Автоследование (по завершении реплики)',
        'コンティニューモード（クリックで切替）:\nなし → オートコンティニュー → オートフォロー\n→  オートコンティニュー（ポストウェイト後）\n↳  オートフォロー（キュー完了後）',
        'وضع المتابعة (انقر للتبديل):\nلا شيء → متابعة تلقائية → تتبع تلقائي\n→  متابعة تلقائية (بعد الانتظار اللاحق)\n↳  تتبع تلقائي (بعد اكتمال الإشارة)',
