        'Volumen de audio incrustado por defecto (dB).',
        'Standardlautstärke für eingebettetes Audio (dB).',
        'Громкость встроенного аудио по умолчанию (dB).',
        '埋め込み音声の既定音量（dB）。',
        'مستوى الصوت المضمّن الافتراضي (dB).',
        'डिफ़ॉल्ट एम्बेडेड ऑडियो वॉल्यूम (dB)।',
