        'Peak-Clamp-Decke nach dem Mix (dBFS). Samples über diesem Absolutpegel werden begrenzt. 0dB = Vollaussteuerung.',
        'Потолок ограничения пиков после сведения (dBFS). Сэмплы выше этого абсолютного уровня ограничиваются. 0dB = полная шкала.',
        'ミックス後のピーククランプ上限（dBFS）。この絶対レベルを超えるサンプルは制限されます。0dB = フルスケール。',
