        'Sitzungsweite Verstärkung für sämtliches Cue-Audio (eigenständig und in Video eingebettet). dB eingeben (0dB = voll).',
        'Сессионное усиление всего аудио реплик (отдельного и встроенного в видео). Введите dB (0dB = полностью).',
